//! 与操作系统无关的纯函数：剪切板原始字节的解码与标记判断。
//! 单独成模块是为了在任何平台都能 `cargo test`（Windows 代码本身只能在 Windows 上运行）。

/// nspasteboard.org 约定的敏感标记 UTI：任一 item 带其中之一，整次复制视为敏感。
pub const SENSITIVE_UTIS: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

pub fn is_sensitive_uti(uti: &str) -> bool {
    SENSITIVE_UTIS.contains(&uti)
}

/// 解码 `CF_UNICODETEXT` 内存块：UTF-16LE，以 NUL 结尾，块尾可能有多余字节。
/// 返回解码后的字符串，以及截到首个 NUL（不含）的原始字节，供日后原样写回。
pub fn utf16le_cstr(bytes: &[u8]) -> (String, Vec<u8>) {
    let wide: Vec<u16> = bytes
        .as_chunks::<2>()
        .0
        .iter()
        .map(|&c| u16::from_le_bytes(c))
        .take_while(|&c| c != 0)
        .collect();
    (
        String::from_utf16_lossy(&wide),
        bytes[..wide.len() * 2].to_vec(),
    )
}

/// `CanIncludeInClipboardHistory` 等 DWORD 标记：值为 0 表示“不要记录”。
pub fn dword_is_zero(bytes: &[u8]) -> bool {
    bytes
        .first_chunk::<4>()
        .map(|&v| u32::from_le_bytes(v) == 0)
        .unwrap_or(false)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn utf16(s: &str, nul: bool) -> Vec<u8> {
        let mut v: Vec<u8> = s.encode_utf16().flat_map(u16::to_le_bytes).collect();
        if nul {
            v.extend([0, 0]);
        }
        v
    }

    #[test]
    fn decodes_and_cuts_at_nul() {
        let mut block = utf16("你好 xPaste", true);
        block.extend(b"junk after nul");
        let (text, raw) = utf16le_cstr(&block);
        assert_eq!(text, "你好 xPaste");
        assert_eq!(raw, utf16("你好 xPaste", false));
    }

    #[test]
    fn handles_missing_nul_and_odd_trailing_byte() {
        let mut block = utf16("ab", false);
        block.push(0x41); // 多出的半个字符
        let (text, raw) = utf16le_cstr(&block);
        assert_eq!(text, "ab");
        assert_eq!(raw.len(), 4);
    }

    #[test]
    fn empty_block_is_empty_text() {
        assert_eq!(utf16le_cstr(&[]), (String::new(), Vec::new()));
        assert_eq!(utf16le_cstr(&[0, 0]), (String::new(), Vec::new()));
    }

    #[test]
    fn dword_zero_detection() {
        assert!(dword_is_zero(&[0, 0, 0, 0]));
        assert!(dword_is_zero(&[0, 0, 0, 0, 9]));
        assert!(!dword_is_zero(&[1, 0, 0, 0]));
        assert!(!dword_is_zero(&[0, 0, 0])); // 不足 4 字节不算标记
    }

    #[test]
    fn sensitive_uti_match_is_exact() {
        assert!(is_sensitive_uti("org.nspasteboard.ConcealedType"));
        assert!(is_sensitive_uti("org.nspasteboard.AutoGeneratedType"));
        assert!(!is_sensitive_uti("org.nspasteboard.concealedtype"));
        assert!(!is_sensitive_uti("public.utf8-plain-text"));
    }
}
